<script>window.__noAi=true;
window.__loc=(()=>{const w=()=>{try{return parent!==window&&parent.location.href?parent:window}catch{return window}};
return{get href(){return w().location.href},get origin(){return w().location.origin},get protocol(){return w().location.protocol},get host(){return w().location.host},get hostname(){return w().location.hostname},
get pathname(){return w().location.pathname},get search(){return w().location.search},get hash(){return w().location.hash},reload(){w().location.reload()},assign(u){w().location.assign(u)},replace(u){w().location.replace(u)}};})();
window.__hist={replaceState:(...a)=>{try{(parent!==window?parent:window).history.replaceState(...a)}catch{}}};
// keep the tab title in sync with the app
addEventListener('DOMContentLoaded',()=>{const t=()=>{try{if(parent!==window)parent.document.title=document.title}catch{}};t();new MutationObserver(t).observe(document.head,{subtree:true,childList:true,characterData:true});});</script>
