    split:`<path d="M12 3v18M6 5h3.5A2.5 2.5 0 0 1 12 7.5v9A2.5 2.5 0 0 1 9.5 19H6a3 3 0 0 1-3-3V8a3 3 0 0 1 3-3Z"/><path d="M18 5h-3.5A2.5 2.5 0 0 0 12 7.5v9a2.5 2.5 0 0 0 2.5 2.5H18a3 3 0 0 0 3-3V8a3 3 0 0 0-3-3Z"/>`,
    dev:`<path d="m8 8-4 4 4 4M16 8l4 4-4 4M14 5l-4 14"/>`,
    plus:`<path d="M12 5v14M5 12h14"/>`,
    search:`<path d="m20 20-3.8-3.8M17.25 11a6.25 6.25 0 1 1-12.5 0 6.25 6.25 0 0 1 12.5 0Z"/>`
  };
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS_V2[name] || icons[name] || ''}</svg>`;
}

