  <script>/* p/js/app/suggest.js */
// search suggestion dropdown. serialised into internal pages, so it must stay self-contained

function attachSuggest(input, onPick) {
  const host = input.parentElement;
  if (!document.getElementById('sg-style')) {
    const st = document.createElement('style');
    st.id = 'sg-style';
    st.textContent = '.sg-host{position:relative;z-index:30}.sg-list{position:absolute;left:0;right:0;top:calc(100% + 6px);z-index:60;padding:6px;border-radius:16px;background:var(--surface-3);border:1px solid var(--border-faint);box-shadow:0 18px 40px -16px rgba(0,0,0,.6);display:none}.sg-list.open{display:block}.sg-item{display:block;width:100%;height:36px;padding:0 12px;border:0;border-radius:10px;background:transparent;color:var(--text-secondary);font-size:13px;text-align:left;text-transform:none;cursor:pointer;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.sg-item:hover,.sg-item.on{background:var(--accent-soft);color:var(--text-white)}.sg-label{padding:4px 12px 6px;color:var(--text-faint);font-size:11px}';
    document.head.appendChild(st);
  }
  host.classList.add('sg-host');
  const list = document.createElement('div');
  list.className = 'sg-list';
  list.setAttribute('role', 'listbox');
  host.appendChild(list);
  const cache = new Map();
  let items = [], idx = -1, typed = '', last = [], ctl = null, timer = null;

  const history = () => { try { return JSON.parse(localStorage.getItem('mochiiHistory') || '[]'); } catch { return []; } };
  const close = () => { list.classList.remove('open'); idx = -1; };
  const mark = () => [...list.querySelectorAll('.sg-item')].forEach((el, i) => el.classList.toggle('on', i === idx));

  function render(arr, label) {
    items = arr.slice(0, 5);
    list.innerHTML = '';
    if (!items.length) return close();
    if (label) { const l = document.createElement('div'); l.className = 'sg-label'; l.textContent = label; list.appendChild(l); }
    items.forEach(text => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'sg-item';
      b.setAttribute('role', 'option');
      b.textContent = text;
      b.addEventListener('mousedown', e => e.preventDefault());
      b.addEventListener('click', () => { input.value = text; close(); onPick(text); });
      list.appendChild(b);
    });
    idx = -1;
    list.classList.add('open');
  }

  async function fetchSuggestions(q, signal) {
    const enc = encodeURIComponent(q);
    const urls = ['https://duckduckgo.com/ac/?type=list&q=' + enc, 'https://suggestqueries.google.com/complete/search?client=firefox&q=' + enc];
    for (const u of urls) {
      try {
        const r = await fetch(u, { signal });
        const d = await r.json();
        if (Array.isArray(d) && Array.isArray(d[1]) && d[1].length) return d[1].map(String);
      } catch (e) { if (e.name === 'AbortError') throw e; }
    }
    return [];
  }

  function update() {
    const v = input.value.trim();
    typed = v;
    clearTimeout(timer);
    if (ctl) ctl.abort();
    if (!v) { const h = history(); return h.length ? render(h, 'recent') : close(); }
    if (/^https?:\/\//i.test(v)) return close();
    const key = v.toLowerCase();
    if (cache.has(key)) { last = cache.get(key); return render(last); }
    const quick = last.filter(s => s.toLowerCase().startsWith(key) && s.toLowerCase() !== key);
    if (quick.length) render(quick);
    timer = setTimeout(async () => {
      ctl = new AbortController();
      try {
        const res = await fetchSuggestions(v, ctl.signal);
        if (input.value.trim() !== v) return;
        cache.set(key, res);
        last = res;
        render(res);
      } catch {}
    }, 70);
  }

  input.addEventListener('input', update);
  input.addEventListener('focus', () => { if (!input.value.trim()) update(); });
  input.addEventListener('blur', close);
  input.addEventListener('keydown', e => {
    if (e.key === 'Escape') return close();
    if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && list.classList.contains('open') && items.length) {
      e.preventDefault();
      const n = items.length;
      idx = e.key === 'ArrowDown' ? (idx + 1) % n : (idx - 1 + n) % n;
      input.value = items[idx];
      mark();
      return;
    }
    if (e.key === 'Enter') close();
  });
  return { close };
}

</script>
  <script>/* p/js/app/pages/shared.js */
// shared shell for internal pages (home, games, chat, ai, music). each page is built as an html string
// and served from a blob url, so baseScript and page scripts are serialised with toString()
// and must not reference anything outside their own body

const THEME_VARS = ['--bg-body','--surface-0','--surface-2','--surface-3','--surface-4','--surface-5','--surface-hover',
  '--text-primary','--text-secondary','--text-muted','--text-faint','--text-white','--border-subtle','--border-faint',
  '--accent','--accent-soft','--accent-active','--input','--search-inset','--search-inset-focus','--search-glow','--font','--font-weight'];

function readThemeVars() {
  const s = getComputedStyle(document.documentElement);
  const vars = {};
  THEME_VARS.forEach(v => { vars[v] = s.getPropertyValue(v).trim(); });
  return vars;
}

async function getFontHead() {
  const cssUrl = 'https://fonts.googleapis.com/css2?family=Lexend:wght@300..600&display=swap';
  try {
    const cached = localStorage.getItem('mochiiFontCss');
    if (cached) return `<style>${cached}</style>`;
  } catch {}
  try {
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), 5000);
    let css = await (await fetch(cssUrl, { signal: ctl.signal })).text();
    clearTimeout(timer);
    const urls = [...new Set([...css.matchAll(/url\((https:[^)]+)\)/g)].map(m => m[1]))];
    const data = await Promise.all(urls.map(async u => {
      const blob = await (await fetch(u)).blob();
      return new Promise(res => { const r = new FileReader(); r.onload = () => res(r.result); r.readAsDataURL(blob); });
    }));
    urls.forEach((u, i) => { css = css.split(u).join(data[i]); });
    try { localStorage.setItem('mochiiFontCss', css); } catch {}
    return `<style>${css}</style>`;
  } catch {
    return `<link rel="stylesheet" href="${cssUrl}">`;
  }
}
const PAGE_CSS = `
  :root{--radius-item:10px;--radius-control:15px;--radius-panel:15px;--radius-dialog:20px;--radius-bar:25px;
    --font:'Lexend',sans-serif;--font-weight:450;--bg-body:#050505;--surface-0:#060606;--surface-2:#0e0e0e;--surface-3:#111;--surface-4:#141414;
    --surface-5:#181818;--surface-hover:#242424;--text-primary:#ebebeb;--text-secondary:#c8c8c8;--text-muted:#8c8c8c;
    --text-faint:#646464;--text-white:#fafafa;--border-subtle:rgba(255,255,255,.05);--border-faint:rgba(255,255,255,.1);
    --accent:#fff;--accent-soft:rgba(255,255,255,.08);--accent-active:rgba(255,255,255,.12);--input:#181818;
    --search-inset:#0d0d0d;--search-inset-focus:#111;--search-glow:rgba(255,255,255,.16)}
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{width:100%;height:100%}
  body{background:var(--bg-body);color:var(--text-primary);font-family:var(--font),'Lexend',sans-serif;font-weight:var(--font-weight,400);text-transform:lowercase;
    -webkit-font-smoothing:antialiased;overflow:hidden;position:relative}
  button,input{font:inherit;color:inherit;text-transform:lowercase}
  button{border:0;background:none;cursor:pointer}
  ::selection{background:var(--accent);color:var(--bg-body)}
  ::-webkit-scrollbar{width:3px;height:3px}::-webkit-scrollbar-track{background:transparent}
  ::-webkit-scrollbar-thumb{background:#4e4e4e;border-radius:999px}
  *{scrollbar-width:thin;scrollbar-color:#4e4e4e transparent}
  :root{--bar-h:52px;--bar-space:calc(var(--bar-h) + 24px);--on-accent:var(--bg-body);--motion:cubic-bezier(.4,0,.2,1);--motion-slow:.38s}
  @keyframes soft-rise{from{opacity:0;transform:translateY(12px) scale(.985)}to{opacity:1;transform:none}}
  @media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}
  .rail{--rail-r:18px;position:absolute;top:14px;left:50%;transform:translateX(-50%);z-index:50;display:flex;align-items:center;gap:22px;height:var(--bar-h);padding:0 22px;border-radius:var(--rail-r);
    background:var(--surface-4);background:color-mix(in srgb,var(--surface-5) 88%,transparent);border:1px solid var(--border-faint);
    box-shadow:0 0 0 3px color-mix(in srgb,var(--bg-body) 60%,transparent),0 14px 32px -12px rgba(0,0,0,.7),inset 0 1px 0 rgba(255,255,255,.03);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px)}
  .rail-nav,.rail-foot{display:flex;align-items:center;gap:22px}
  .rail-btn{position:relative;width:40px;height:40px;display:flex;align-items:center;justify-content:center;border-radius:calc(var(--rail-r) - (var(--bar-h) - 40px) / 2);color:var(--text-faint);transition:background .12s,color .12s}
  .rail-btn:hover{background:var(--accent-soft);color:var(--text-secondary)}
  .rail-btn:active{background:var(--accent-active)}
  .rail-btn.on{color:var(--text-white);background:var(--accent-soft)}
  .rail-btn.on::before{content:"";position:absolute;bottom:3px;left:50%;width:4px;height:4px;margin-left:-2px;border-radius:50%;background:var(--accent);box-shadow:0 0 8px var(--accent);animation:rail-dot .32s var(--motion) both}
  @keyframes rail-dot{from{opacity:0;transform:scale(0)}to{opacity:1;transform:none}}
  .rail-btn::after{content:attr(data-tip);position:absolute;top:calc(100% + 14px);left:50%;transform:translate(-50%,-4px);padding:6px 10px;border-radius:9px;background:var(--surface-5);border:1px solid var(--border-faint);color:var(--text-white);font-size:12px;line-height:1;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .12s,transform .12s}
  .rail-btn:hover::after,.rail-btn:focus-visible::after{opacity:1;transform:translate(-50%,0)}
  .rail-btn:focus-visible,.icon-btn:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
  .acct-pill{position:absolute;top:14px;right:14px;z-index:50;display:flex;align-items:center;gap:10px;height:var(--bar-h);max-width:220px;padding:0 18px 0 7px;border-radius:999px;
    background:var(--surface-4);background:color-mix(in srgb,var(--surface-5) 88%,transparent);border:1px solid var(--border-faint);color:var(--text-secondary);font-size:13px;
    box-shadow:0 0 0 3px color-mix(in srgb,var(--bg-body) 60%,transparent),0 14px 32px -12px rgba(0,0,0,.7),inset 0 1px 0 rgba(255,255,255,.03);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);transition:color .12s,border-color .12s}
  .acct-pill[hidden]{display:none}
  .acct-pill:hover{color:var(--text-white);border-color:var(--border-subtle)}
  .acct-pill:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
  .acct-pill-pic{width:calc(var(--bar-h) - 14px);height:calc(var(--bar-h) - 14px);flex:0 0 auto;display:flex;align-items:center;justify-content:center;border-radius:50%;overflow:hidden;background:var(--surface-hover);color:var(--text-white);font-size:14px}
  .acct-pill-pic img{width:100%;height:100%;object-fit:cover;display:block}
  .acct-pill-name{min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
  @media (max-width:1000px){.acct-pill{padding:0 6px}.acct-pill-name{display:none}}
  .rail-music{position:absolute;top:100%;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center}
  body[data-view=music] .rail-music{display:none}
  .rm-tab{width:46px;height:17px;display:flex;align-items:center;justify-content:center;border-radius:0 0 11px 11px;background:var(--surface-4);background:color-mix(in srgb,var(--surface-5) 92%,transparent);
    border:1px solid var(--border-faint);border-top:0;color:var(--text-faint);transition:color .12s,height .15s var(--motion)}
  .rm-tab:hover,.rm-tab:focus-visible,.rail-music.open .rm-tab{color:var(--text-white);height:21px;outline:none}
  .rail-music.playing .rm-tab{color:var(--accent)}
  .rm-pop{margin-top:8px;display:none;align-items:center;gap:4px;width:min(320px,calc(100vw - 24px));height:46px;padding:0 6px;border-radius:15px;background:var(--surface-4);
    background:color-mix(in srgb,var(--surface-5) 96%,transparent);border:1px solid var(--border-faint);box-shadow:0 0 0 3px color-mix(in srgb,var(--bg-body) 60%,transparent),0 18px 36px -14px rgba(0,0,0,.75)}
  .rail-music.open .rm-pop{display:flex;animation:soft-rise .2s var(--motion) both}
  .rm-now{flex:1;min-width:0;display:flex;align-items:center;gap:10px;height:34px;padding:0 6px;border-radius:10px;text-align:left;transition:background .12s}
  .rm-now:hover{background:var(--accent-soft)}
  .rm-cov{position:relative;width:28px;height:28px;flex:0 0 28px;border-radius:8px;overflow:hidden;display:flex;align-items:center;justify-content:center;color:var(--text-muted)}
  .rm-cov img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
  .rm-cov img[hidden]{display:none}
  .rm-txt{min-width:0;display:flex;flex-direction:column;line-height:1.3;text-transform:none}
  .rm-txt b,.rm-txt small{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
  .rm-txt b{font-weight:450;font-size:12.5px;color:var(--text-secondary)}
  .rm-txt small{font-size:11px;color:var(--text-faint)}
  .rm-ctl{display:flex;align-items:center;gap:1px;flex:0 0 auto}
  .rm-ctl button{width:30px;height:30px;display:flex;align-items:center;justify-content:center;border-radius:9px;color:var(--text-muted);transition:background .12s,color .12s}
  .rm-ctl button:hover{background:var(--accent-soft);color:var(--text-white)}
  .rm-ctl button>span{display:flex}
  .rm-ctl .i-pause,.rail-music.playing .rm-ctl .i-play{display:none}
  .rail-music.playing .rm-ctl .i-pause{display:flex}
  .rail-music:not(.has-track) .rm-ctl button{opacity:.35;pointer-events:none}
  .rm-tab:focus-visible,.rm-now:focus-visible,.rm-ctl button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
  .rail-tab{position:absolute;top:0;left:50%;z-index:51;width:52px;height:20px;display:none;align-items:center;justify-content:center;border-radius:0 0 12px 12px;
    background:var(--surface-4);background:color-mix(in srgb,var(--surface-5) 88%,transparent);border:1px solid var(--border-faint);border-top:0;color:var(--text-muted);
    -webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);transform:translate(-50%,-100%);transition:transform var(--motion-slow) var(--motion),color .12s,height .12s}
  .rail-tab:hover,.rail-tab:focus-visible{color:var(--text-white);height:24px;outline:none}
  body.rail-collapsible .rail-tab{display:flex}
  body:not(.rail-collapsible) .rail-btn[data-rail-toggle]{display:none}
  body.rail-collapsible .rail,body.rail-collapsible .acct-pill{transition:transform var(--motion-slow) var(--motion),opacity .25s,visibility 0s,color .12s,border-color .12s}
