  body.rail-min .acct-pill{transform:translateY(calc(-100% - 24px));opacity:0;visibility:hidden;transition:transform var(--motion-slow) var(--motion),opacity .25s,visibility 0s var(--motion-slow)}
  body.rail-min .rail-tab{transform:translate(-50%,0);transition:transform var(--motion-slow) var(--motion) .12s,color .12s,height .12s}
  .icon-btn{width:34px;height:34px;flex:0 0 34px;display:flex;align-items:center;justify-content:center;border-radius:11px;background:var(--surface-3);border:1px solid var(--border-subtle);color:var(--text-muted);transition:background .12s,color .12s}
  .icon-btn:hover{background:var(--surface-5);color:var(--text-white)}
  .searchbar{position:relative;width:100%}
  .searchbar>svg{position:absolute;left:18px;top:50%;transform:translateY(-50%);color:var(--text-muted);pointer-events:none;transition:color .15s}
