  <script>/* p/js/app/proxy.js */
// wisp servers and the scramjet / ultraviolet / bare-mux loaders

let WISP_SERVERS = [
  { name:'mochii', url:'wss://mochiiibackend.share.zrok.io/study/' },
  { name:'zaka', url:'wss://zka.solidaritysafaris.com/api/'},
  { name:'nyx', url:'wss://nyxlearning.org/wisp/'},
];
let DEFAULT_WISP = window.SITE_CONFIG?.defaultWisp ?? null;
const PROXIES = [
  { key: 'scramjet', label: 'scramjet', note: 'the newer engine. fast and modern.' },
  { key: 'ultraviolet', label: 'ultraviolet', note: 'the long established engine. wide compatibility.' }
];
const bootProxy = (() => {
  try { return localStorage.getItem('mochiiSetting:proxy') === 'ultraviolet' ? 'ultraviolet' : 'scramjet'; } catch { return 'scramjet'; }
})();
// the engine actually running. falls back to scramjet if ultraviolet can't load, without
// touching the saved setting (account sync and the wizard compare against bootProxy)
let activeProxy = bootProxy;
let sharedScramjet = null;
let sharedConnection = null;
let sharedConnectionReady = false;
let scramjetLoadPromise = null;
let bareMuxLoadPromise = null;
// epoxy (default) or libcurl, both with a few host aliases (see p/js/transport.mjs). switching takes effect on reload. the bare-mux worker imports it, so it needs a full url
const bootTransport = (() => {
  try { return localStorage.getItem('mochiiSetting:transport') === 'libcurl' ? 'libcurl' : 'epoxy'; } catch { return 'epoxy'; }
})();
const TRANSPORT_URL = __loc.origin + getBasePath() + (bootTransport === 'libcurl' ? 'p/js/transport.mjs' : 'p/js/transport-epoxy.mjs');
async function fetchWispServers() {
  if (!DEFAULT_WISP) DEFAULT_WISP = WISP_SERVERS[0]?.url || null;
  { const cur = localStorage.getItem('proxServer'); if (DEFAULT_WISP && (!cur || !getAllWispServers().some(s => s.url === cur))) localStorage.setItem('proxServer', DEFAULT_WISP); }
}

const getStoredWisps = () => {
  try { return JSON.parse(localStorage.getItem('customWisps') || '[]'); }
  catch { return []; }
};

function getAllWispServers() { return [...WISP_SERVERS, ...getStoredWisps()]; }

async function pingWispServer(url, timeout = 4000) {
  return new Promise(resolve => {
    const start = Date.now();
    try {
      const ws = new WebSocket(url);
      const timer = setTimeout(() => {
        try { ws.close(); } catch {}
        resolve({url, success:false, latency:null});
      }, timeout);
      ws.onopen = () => {
        clearTimeout(timer);
        const latency = Date.now() - start;
        try { ws.close(); } catch {}
        resolve({url, success:true, latency});
      };
      ws.onerror = () => {
        clearTimeout(timer);
        try { ws.close(); } catch {}
        resolve({url, success:false, latency:null});
      };
    } catch {
      resolve({url, success:false, latency:null});
    }
  });
}

async function findBestWispServer(servers, currentUrl) {
  if (!servers?.length) return currentUrl;
  const results = await Promise.all(servers.map(s => pingWispServer(s.url)));
  const working = results.filter(r => r.success).sort((a,b) => a.latency - b.latency);
  return working[0]?.url || currentUrl || servers[0]?.url;
}

async function initializeWithBestServer() {
  const autoswitch = localStorage.getItem('wispAutoswitch') !== 'false';
  const allServers = getAllWispServers();
  if (!autoswitch || allServers.length <= 1) return;
  const currentUrl = localStorage.getItem('proxServer') || DEFAULT_WISP;
  const currentCheck = await pingWispServer(currentUrl);
  if (currentCheck.success) return;
  const best = await findBestWispServer(allServers, currentUrl);
  if (best && best !== currentUrl) localStorage.setItem('proxServer', best);
}

async function ensureScramjetLoaded() {
  if (typeof globalThis.$scramjetLoadController === 'function') return;

  if (!scramjetLoadPromise) {
    scramjetLoadPromise = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = getBasePath() + 'p/js/homework/math.all.js';
      script.onload = () => {
        if (typeof globalThis.$scramjetLoadController === 'function') resolve();
        else reject(new Error('scramjet loaded but controller is unavailable'));
      };
      script.onerror = () => reject(new Error('could not load scramjet'));
      document.head.appendChild(script);
    });
  }

  await scramjetLoadPromise;
}

function uvPrefix() { return getBasePath() + 'uv/'; }

async function loadUltraviolet() {
  if (globalThis.Ultraviolet) return;
  await new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = getBasePath() + 'p/js/homework/uv.bundle.js';
    script.onload = resolve;
    script.onerror = () => reject(new Error('could not load ultraviolet'));
    document.head.appendChild(script);
  });
  if (!globalThis.Ultraviolet) throw new Error('ultraviolet loaded but is unavailable');
}

function createUvFrame() {
  const iframe = document.createElement('iframe');
  const listeners = [];
  let current = '';
  let attached = false;
  // the old page stays in the frame until the new one loads, so ignore its url until then
  let stale = '';
  iframe.addEventListener('load', () => { stale = ''; });
  const emit = url => { current = url; listeners.forEach(fn => fn({ url })); };
  const read = () => {
    try {
      const cw = iframe.contentWindow;
      const loc = cw && cw.__uv$location;
      if (loc && loc.href) return String(loc.href);
      const full = __loc.origin + uvPrefix();
      const href = cw.location.href;
      if (href.indexOf(full) === 0) return globalThis.Ultraviolet.codec.xor.decode(href.slice(full.length));
    } catch {}
    return '';
  };
  const poll = setInterval(() => {
    if (!iframe.isConnected) { if (attached) clearInterval(poll); return; }
    attached = true;
    const url = read();
    if (url && url === stale) return;
    if (url) stale = '';
    if (url && url !== current && /^https?:/i.test(url)) emit(url);
  }, 300);
  return {
    frame: iframe,
    go(url) {
      // match the form the frame reports back (e.g. trailing slash), so one navigation is one history entry
      try { url = new URL(url).href; } catch {}
      if (current && current !== url) stale = current;
      emit(url);
      iframe.src = uvPrefix() + globalThis.Ultraviolet.codec.xor.encode(url);
    },
    addEventListener(type, fn) { if (type === 'urlchange') listeners.push(fn); }
  };
}

async function initProxyEngine() {
  if (bootProxy === 'ultraviolet') {
    try { await loadUltraviolet(); return; }
    catch (e) { console.warn('ultraviolet unavailable, using scramjet:', e); activeProxy = 'scramjet'; }
  }
  await getSharedScramjet();
}

async function getSharedScramjet() {
  if (sharedScramjet) return sharedScramjet;

  await ensureScramjetLoaded();

  const { ScramjetController } = globalThis.$scramjetLoadController();

  sharedScramjet = new ScramjetController({
    prefix: getBasePath() + 'scramjet/',
    files: {
      wasm:getBasePath()+'p/js/homework/math.wasm.wasm',
      all:getBasePath()+'p/js/homework/math.all.js',
      sync:getBasePath()+'p/js/homework/math.sync.js'
    }
  });

  await sharedScramjet.init();
  return sharedScramjet;
}

async function ensureBareMuxLoaded() {
  if (window.BareMux) return window.BareMux;

  if (!bareMuxLoadPromise) {
    bareMuxLoadPromise = import(
      getBasePath() + 'p/js/lib/bare-mux.mjs'
    ).then(mod => {
      window.BareMux = mod;
      return mod;
    });
  }

  return bareMuxLoadPromise;
}

async function getSharedConnection() {
  if (sharedConnectionReady) return sharedConnection;

  const BM = await ensureBareMuxLoaded();

  if (!BM?.BareMuxConnection) {
    throw new Error('bare-mux failed to load');
  }

  const wispUrl = localStorage.getItem('proxServer') || DEFAULT_WISP;

  sharedConnection = new BM.BareMuxConnection(getBasePath() + 'bareworker.js');

  await sharedConnection.setTransport(TRANSPORT_URL, [{ wisp:wispUrl }]);

  sharedConnectionReady = true;
  return sharedConnection;
}

