  <script>/* p/js/app/extensions.js */
// browser extension storage, packaging and content-script runtime

const EXTENSION_LIBRARY = [
];

const EXTENSION_DB_NAME='mochiiExtensions', EXTENSION_DB_VERSION=2, EXTENSION_DB_STORE='extensions';
let EXTENSIONS=[];
let extensionRuntimeRevision=0;
let extensionDbPromise=null;

function extClone(obj){return JSON.parse(JSON.stringify(obj))}
function extensionId(){return 'custom-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10)}

function openExtensionDb(){
  if(extensionDbPromise)return extensionDbPromise;
  extensionDbPromise=new Promise((resolve,reject)=>{
    if(!('indexedDB'in window)){reject(new Error('indexeddb unavailable'));return}
    const req=indexedDB.open(EXTENSION_DB_NAME,EXTENSION_DB_VERSION);
    req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(EXTENSION_DB_STORE))db.createObjectStore(EXTENSION_DB_STORE,{keyPath:'id'})};
    req.onsuccess=()=>resolve(req.result); req.onerror=()=>reject(req.error||new Error('could not open extension storage'));
  });
  return extensionDbPromise;
}
async function getAllStoredExtensions(){
  try{const db=await openExtensionDb();return await new Promise((resolve,reject)=>{const tx=db.transaction(EXTENSION_DB_STORE,'readonly'),req=tx.objectStore(EXTENSION_DB_STORE).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error)})}
  catch{try{return JSON.parse(localStorage.getItem('mochiiExtensions')||'[]')}catch{return []}}
}
async function putStoredExtension(ext){
  const clean=extClone(ext);
  try{const db=await openExtensionDb();await new Promise((resolve,reject)=>{const tx=db.transaction(EXTENSION_DB_STORE,'readwrite');tx.objectStore(EXTENSION_DB_STORE).put(clean);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
