function extensionMatchPattern(pattern,url){
  if(pattern==='<all_urls>')return /^https?:/i.test(url||'');
  try{
    const u=new URL(url),m=String(pattern||'').match(/^([*a-z]+):\/\/([^/]+)(\/.*)?$/i); if(!m)return false;
    const scheme=m[1].toLowerCase(),host=m[2].toLowerCase(),path=m[3]||'/';
    if(scheme!=='*'&&scheme!==u.protocol.slice(0,-1))return false;
    if(host!=='*'&&!host.startsWith('*.')&&host!==u.hostname.toLowerCase())return false;
    if(host.startsWith('*.')&&u.hostname.toLowerCase()!==host.slice(2)&&!u.hostname.toLowerCase().endsWith('.'+host.slice(2)))return false;
