}
function extensionToolbarLabel(ext){return String(ext?.name||'ext').trim().slice(0,2).toUpperCase()}

function updateExtensionToolbar(){
  const bar=document.getElementById('extension-toolbar'),tab=getActiveTab(); if(!bar)return;
  const browsing=!!tab&&!tab.page&&!!tab.url&&document.getElementById('browser-container')?.classList.contains('browsing-mode');
  bar.classList.toggle('visible',browsing&&EXTENSIONS.some(x=>x.enabled)); bar.innerHTML=''; if(!browsing)return;
  EXTENSIONS.filter(x=>x.enabled).forEach(ext=>{
    const b=document.createElement('button'); b.type='button'; b.className='extension-toolbar-button';
    b.title=`${ext.name}${getManifestPopup(ext)?' · open popup':' · extension'}`;
    const iconPath=getManifestIconPath(ext),iconUrl=iconPath?extensionFileAsUrl(ext,iconPath):null;
    b.innerHTML=iconUrl?`<img src="${iconUrl}" alt="">`:`<span>${escapeHtml(extensionToolbarLabel(ext))}</span>`;
    b.onclick=()=>getManifestPopup(ext)?openExtensionSurface(ext.id,'popup'):toggleExtension(ext.id);
    bar.appendChild(b);
  });
}

async function executeExtensionScript(win,code,label){
  if(!code)return;
  const source=String(code);
  try{win.eval(source);return}catch{}
  try{const s=win.document.createElement('script');s.textContent=source;(win.document.head||win.document.documentElement).appendChild(s);s.remove()}catch(e){console.warn('extension script failed',label,e)}
}

async function runExtensionsForTab(tab,force=false){
  if(!tab||tab.page||!tab.url||!tab.frame?.frame?.contentWindow)return;
  if(!force&&tab._extensionRevision===extensionRuntimeRevision&&tab._extensionUrl===tab.url)return;
  const win=tab.frame.frame.contentWindow,url=tab.url;
  for(const ext of EXTENSIONS){
    if(!ext.enabled||!extensionMatches(ext,url))continue;
    for(const cs of (ext.manifest?.content_scripts||[])){
      if(!(cs.matches||[]).some(p=>extensionMatchPattern(p,url)))continue;
      for(const cssFile of (cs.css||[])){
        const key=resolveExtensionPath(ext._manifestBase,cssFile),css=extensionFileText(ext,key);if(!css)continue;
        try{const safeId=String(ext.id+'-'+key).replace(/[^a-z0-9_-]/gi,'_');if(!win.document.querySelector(`style[data-mochii-extension="${safeId}"]`)){const st=win.document.createElement('style');st.dataset.mochiiExtension=safeId;st.textContent=css;(win.document.head||win.document.documentElement).appendChild(st)}}catch{}
      }
      for(const jsFile of (cs.js||[])){
        const key=resolveExtensionPath(ext._manifestBase,jsFile),js=extensionFileText(ext,key);if(!js)continue;
        try{const marker=ext.id+':'+key;win.__mochiiExtensionScripts=win.__mochiiExtensionScripts||{};if(win.__mochiiExtensionScripts[marker])continue;win.__mochiiExtensionScripts[marker]=true;await executeExtensionScript(win,js,ext.name+' '+key)}catch{}
