function extensionFilesToJson(files){return files}
function bytesToBase64(buffer){
  const bytes=new Uint8Array(buffer),chunk=0x8000;let out='';
  for(let i=0;i<bytes.length;i+=chunk)out+=String.fromCharCode(...bytes.subarray(i,Math.min(i+chunk,bytes.length)));
  return btoa(out);
}
function base64ToDataUrl(data,type){return `data:${type||'application/octet-stream'};base64,${data}`}

async function blobToStoredFile(blob,path){
  const name=normalizeExtensionPath(path),type=blob.type||extensionMime(name);
  if(extensionTextFile(name))return {kind:'text',data:await blob.text(),type};
  return {kind:'data',data:bytesToBase64(await blob.arrayBuffer()),type};
}

async function readPackageFilesFromZip(file){
  if(!window.JSZip)await new Promise((res,rej)=>{const s=document.createElement('script');s.src=getBasePath()+'p/js/lib/jszip.min.js';s.onload=res;s.onerror=()=>rej(new Error('could not load jszip'));document.head.appendChild(s);});const Zip=window.JSZip,zip=await Zip.loadAsync(file),names=Object.keys(zip.files);
  const manifestPath=names.find(n=>!zip.files[n].dir&&/(^|\/)manifest\.json$/i.test(n));if(!manifestPath)throw new Error('manifest.json was not found in the zip');
  const base=manifestPath.slice(0,manifestPath.lastIndexOf('/')+1),manifest=JSON.parse(await zip.file(manifestPath).async('string')),files={};
  for(const name of names){
    if(zip.files[name].dir)continue;
    const normalized=normalizeExtensionPath(name);
    if(extensionTextFile(normalized))files[normalized]={kind:'text',data:await zip.file(name).async('string'),type:extensionMime(normalized)};
    else files[normalized]={kind:'data',data:await zip.file(name).async('base64'),type:extensionMime(normalized)};
  }
  return{manifest,files,base};
}

async function readPackageFilesFromFolder(fileList){
  const arr=[...fileList],mf=arr.find(f=>/(^|\/)manifest\.json$/i.test(f.webkitRelativePath||f.name));if(!mf)throw new Error('manifest.json was not found in the folder');
  const rel=normalizeExtensionPath(mf.webkitRelativePath||mf.name),base=rel.slice(0,rel.lastIndexOf('/')+1),manifest=JSON.parse(await mf.text()),files={};
  for(const file of arr){
    const p=normalizeExtensionPath(file.webkitRelativePath||file.name);
    files[p]=await blobToStoredFile(file,p);
  }
  return{manifest,files,base};
}

function validateExtensionManifest(manifest){
  if(!manifest||typeof manifest!=='object')throw new Error('invalid manifest.json');
  if(manifest.manifest_version!==2&&manifest.manifest_version!==3)throw new Error('only manifest v2/v3 packages are supported');
  if(!manifest.name||!manifest.version)throw new Error('manifest needs a name and version');
  if(!Array.isArray(manifest.content_scripts) && manifest.content_scripts!=null)throw new Error('content_scripts must be an array');
  for(const cs of manifest.content_scripts||[]){
    if(!Array.isArray(cs.matches))throw new Error('every content_scripts entry needs matches');
    for(const f of [...(cs.js||[]),...(cs.css||[])])if(typeof f!=='string'||/^https?:/i.test(f))throw new Error('content script files must be local paths');
  }
}

function extensionFromPackage(pkg,source='custom',idOverride=''){
  validateExtensionManifest(pkg.manifest);
  return{
    id:idOverride||extensionId(),
    name:String(pkg.manifest.name),
    version:String(pkg.manifest.version),
    description:String(pkg.manifest.description||'extension package'),
    source,
    icon:'EXT',
    enabled:false,
    manifest:pkg.manifest,
    files:extensionFilesToJson(pkg.files),
    _manifestBase:pkg.base||'',
    libraryPackage:''
