}

async function installExtensionPackage(pkg,{source='custom',id='',enabled=true,libraryPackage=''}={}){
  const ext=extensionFromPackage(pkg,source,id);ext.enabled=enabled;ext.libraryPackage=libraryPackage;
  await putStoredExtension(ext);EXTENSIONS=await getAllStoredExtensions();renderExtensionControls();updateExtensionToolbar();
  const tab=getActiveTab();if(enabled&&tab&&!tab.page&&tab.url)await runExtensionsForTab(tab,true);return ext;
}

async function fetchLibraryPackage(entry){
  if(!entry?.package)throw new Error('library entry has no package path');
  const url=new URL(entry.package,__loc.href).href;
  const res=await fetch(url,{cache:'no-store'});if(!res.ok)throw new Error(`could not fetch package (${res.status})`);
  return readPackageFilesFromZip(await res.blob());
}
async function installLibraryExtension(id){
  const entry=EXTENSION_LIBRARY.find(x=>x.id===id);if(!entry)return;
  try{
    const pkg=await fetchLibraryPackage(entry);
    const ext=await installExtensionPackage(pkg,{source:'library',id:entry.id,enabled:true,libraryPackage:entry.package});
    if(entry.name)ext.name=entry.name;
    await putStoredExtension({...ext,name:entry.name||ext.name,description:entry.description||ext.description,source:'library',libraryPackage:entry.package});
    EXTENSIONS=await getAllStoredExtensions();renderExtensionControls();updateExtensionToolbar();
    alert(`${ext.name} installed from library`);
  }catch(e){alert(`could not install ${entry.name||id}: ${e?.message||'invalid package'}`)}
}

async function handleExtensionZip(file){try{const ext=await installExtensionPackage(await readPackageFilesFromZip(file),{source:'custom',enabled:true});alert(`${ext.name} installed`)}catch(e){alert(`could not install extension: ${e?.message||'invalid package'}`)}}
async function handleExtensionFolder(files){try{const ext=await installExtensionPackage(await readPackageFilesFromFolder(files),{source:'custom',enabled:true});alert(`${ext.name} installed`)}catch(e){alert(`could not install extension: ${e?.message||'invalid folder'}`)}}
async function toggleExtension(id){const ext=EXTENSIONS.find(x=>x.id===id);if(!ext)return;ext.enabled=!ext.enabled;await putStoredExtension(ext);EXTENSIONS=await getAllStoredExtensions();renderExtensionControls();updateExtensionToolbar();const tab=getActiveTab();if(tab&&!tab.page&&tab.url)reloadTab(tab)}
async function uninstallExtension(id){await deleteStoredExtension(id);EXTENSIONS=await getAllStoredExtensions();renderExtensionControls();updateExtensionToolbar();const tab=getActiveTab();if(tab&&!tab.page&&tab.url)reloadTab(tab)}
async function updateLibraryExtension(id){
  const existing=EXTENSIONS.find(x=>x.id===id);const entry=EXTENSION_LIBRARY.find(x=>x.id===id);if(!entry)return;
  try{const pkg=await fetchLibraryPackage(entry),ext=await installExtensionPackage(pkg,{source:'library',id,enabled:existing?.enabled!==false,libraryPackage:entry.package});ext.name=entry.name||ext.name;ext.description=entry.description||ext.description;await putStoredExtension(ext);EXTENSIONS=await getAllStoredExtensions();renderExtensionControls();updateExtensionToolbar();}catch(e){alert(`could not update ${entry.name||id}: ${e?.message||'invalid package'}`)}
}

function buildExtensionFileMap(ext){
  const map={};
  for(const [path,file] of Object.entries(ext.files||{})){if(file?.kind==='data')map[path]=base64ToDataUrl(file.data,file.type);else map[path]=`data:${file.type||extensionMime(path)};charset=utf-8,${encodeURIComponent(file?.data||'')}`;}
  return map;
}
function extensionSurfaceHtml(ext,entryPath){
  const html=extensionFileText(ext,entryPath);if(html==null)throw new Error('extension page not found: '+entryPath);
  const map=buildExtensionFileMap(ext),dir=entryPath.includes('/')?entryPath.slice(0,entryPath.lastIndexOf('/')+1):'';
  const resolveRef=ref=>{const r=String(ref||'').trim();if(!r||/^(?:https?:|data:|blob:|chrome:|moz-extension:|#|\/\/)/i.test(r))return null;return map[resolveExtensionPath(dir,r)]||null};
  let out=html;
  out=out.replace(/(\b(?:src|href|poster)=\s*["'])([^"']+)(["'])/gi,(m,a,r,c)=>{const u=resolveRef(r);return u?a+u+c:m});
  out=out.replace(/url\((\s*["']?)([^\)"']+)(["']?\s*)\)/gi,(m,a,r,c)=>{const u=resolveRef(r);return u?`url(${a}${u}${c})`:m});
  const shim=`<scr${'ipt'}>\n(()=>{\nconst files=${JSON.stringify(map)};const normal=p=>String(p||'').replace(/^\\.?\\//,'');const request=(type,payload)=>new Promise(resolve=>{const id='m'+Date.now().toString(36)+Math.random().toString(36).slice(2);const fn=e=>{if(e.source!==parent||e.data?.type!=='mochii-extension-result'||e.data.id!==id)return;window.removeEventListener('message',fn);resolve(e.data.value)};window.addEventListener('message',fn);parent.postMessage({type:'mochii-extension-request',id,request:type,payload},'*')});window.chrome=window.chrome||{};window.chrome.runtime=window.chrome.runtime||{};window.chrome.runtime.id=${JSON.stringify(ext.id)};window.chrome.runtime.getURL=p=>files[normal(p)]||files[${JSON.stringify(entryPath)}]||'';window.chrome.runtime.sendMessage=p=>request('runtime.sendMessage',p);window.chrome.storage=window.chrome.storage||{};window.chrome.storage.local={get:k=>request('storage.get',k),set:v=>request('storage.set',v)};window.chrome.tabs=window.chrome.tabs||{};window.chrome.tabs.create=o=>request('tabs.create',o);window.chrome.action=window.chrome.action||{};window.chrome.action.getTitle=()=>Promise.resolve(${JSON.stringify(ext.manifest?.action?.default_title||ext.name)});window.__mochiiExtensionFiles=files;})();\n</scr${'ipt'}>`;
  if(/<head\b[^>]*>/i.test(out))out=out.replace(/<head\b[^>]*>/i,m=>m+shim);else out=shim+out;
