}

function handleExtensionRequest(event,ext){
  const send=value=>event.source?.postMessage({type:'mochii-extension-result',id:event.data.id,value},'*');
  if(event.data.request==='storage.get'){
    let db={};try{db=JSON.parse(localStorage.getItem('mochiiExtStorage:'+ext.id)||'{}')}catch{}
    const k=event.data.payload;if(k==null){send(db);return;} if(typeof k==='string'){send({[k]:db[k]});return;} if(Array.isArray(k)){const o={};k.forEach(x=>o[x]=db[x]);send(o);return;} const o={};Object.keys(k).forEach(x=>o[x]=db[x]===undefined?k[x]:db[x]);send(o);return;
  }
  if(event.data.request==='storage.set'){
    let db={};try{db=JSON.parse(localStorage.getItem('mochiiExtStorage:'+ext.id)||'{}')}catch{};Object.assign(db,event.data.payload||{});try{localStorage.setItem('mochiiExtStorage:'+ext.id,JSON.stringify(db))}catch{};send(undefined);return;
  }
  if(event.data.request==='tabs.create'){
    const url=event.data.payload?.url;if(typeof url==='string'&&/^https?:/i.test(url)){const tab=createTab(true,'home',{forceChrome:true});if(tab)handleSubmit(url);}send({});return;
  }
