}

let extensionSurfaceState=null;
function closeExtensionSurface(){
  const modal=document.getElementById('extension-surface-modal');if(modal)modal.classList.add('hidden');extensionSurfaceState=null;
}
function openExtensionSurface(id,kind='popup'){
  const ext=EXTENSIONS.find(x=>x.id===id);if(!ext)return;
  const path=kind==='options'?getManifestOptions(ext):getManifestPopup(ext);if(!path)return;
  const modal=document.getElementById('extension-surface-modal'),frame=document.getElementById('extension-surface-frame'),title=document.getElementById('extension-surface-title');if(!modal||!frame)return;
  try{frame.srcdoc=extensionSurfaceHtml(ext,path);}catch(e){alert(`could not open extension page: ${e?.message||'invalid page'}`);return;}
  title.textContent=kind==='options'?`${ext.name} · options`:ext.name;extensionSurfaceState={id,kind};modal.classList.remove('hidden');
}

async function initializeExtensions(){
  EXTENSIONS=await getAllStoredExtensions();
  for(const old of EXTENSIONS.filter(x=>x.source==='builtin')) await deleteStoredExtension(old.id);
  EXTENSIONS=await getAllStoredExtensions();
}

function extensionCapabilitySummary(ext){
  const m=ext.manifest||{},parts=[];
  if((m.content_scripts||[]).length)parts.push('content scripts');
  if(getManifestPopup(ext))parts.push('popup');
  if(getManifestOptions(ext))parts.push('options');
  if(getManifestBackground(ext))parts.push('background');
  if((m.permissions||[]).length)parts.push(`${m.permissions.length} permissions`);
  return parts.join(' · ')||'manifest only';
}

function renderExtensionControls(){
  const market=document.getElementById('extension-marketplace'),installed=document.getElementById('extension-installed');if(!market||!installed)return;market.innerHTML='';installed.innerHTML='';

  if(!EXTENSION_LIBRARY.length){
    market.innerHTML='<div class="extension-empty">library is empty. add extension packages to the extension library in the site code.</div>';
  } else {
    for(const item of EXTENSION_LIBRARY){
      const ext=EXTENSIONS.find(x=>x.id===item.id),card=document.createElement('div');card.className='extension-card';
      const installedMeta=ext?`<span class="extension-state">${ext.enabled?'installed · on':'installed · off'}</span>`:'<span class="extension-state">not installed</span>';
      card.innerHTML=`<div class="extension-icon">EXT</div><div class="extension-info"><div class="extension-name">${escapeHtml(item.name||ext?.name||item.id)}</div><div class="extension-meta">library · ${escapeHtml(installedMeta.replace(/<[^>]+>/g,''))}</div><div class="extension-description">${escapeHtml(item.description||ext?.description||'real extension package')}</div></div><div class="extension-actions"></div>`;
      const actions=card.querySelector('.extension-actions');
      if(ext){const toggle=document.createElement('button');toggle.className=`extension-action ${ext.enabled?'active':''}`;toggle.textContent=ext.enabled?'on':'off';toggle.onclick=()=>toggleExtension(ext.id);actions.appendChild(toggle);const update=document.createElement('button');update.className='extension-action';update.textContent='update';update.onclick=()=>updateLibraryExtension(item.id);actions.appendChild(update);if(getManifestOptions(ext)){const options=document.createElement('button');options.className='extension-action';options.textContent='options';options.onclick=()=>openExtensionSurface(ext.id,'options');actions.appendChild(options)}}else{const add=document.createElement('button');add.className='extension-action';add.textContent='add';add.onclick=()=>installLibraryExtension(item.id);actions.appendChild(add)}
      market.appendChild(card);
    }
  }

  for(const ext of EXTENSIONS.filter(x=>x.source!=='library')){
    const card=document.createElement('div');card.className='extension-card';
    card.innerHTML=`<div class="extension-icon">EXT</div><div class="extension-info"><div class="extension-name">${escapeHtml(ext.name)}</div><div class="extension-meta">custom · v${escapeHtml(ext.version)}${ext.enabled?' · on':' · off'}</div><div class="extension-description">${escapeHtml(ext.description)}<span class="extension-capabilities">${escapeHtml(extensionCapabilitySummary(ext))}</span></div></div><div class="extension-actions"></div>`;
    const actions=card.querySelector('.extension-actions');
    const toggle=document.createElement('button');toggle.className=`extension-action ${ext.enabled?'active':''}`;toggle.textContent=ext.enabled?'on':'off';toggle.onclick=()=>toggleExtension(ext.id);actions.appendChild(toggle);
    if(getManifestPopup(ext)){const popup=document.createElement('button');popup.className='extension-action';popup.textContent='popup';popup.onclick=()=>openExtensionSurface(ext.id,'popup');actions.appendChild(popup)}
    if(getManifestOptions(ext)){const options=document.createElement('button');options.className='extension-action';options.textContent='options';options.onclick=()=>openExtensionSurface(ext.id,'options');actions.appendChild(options)}
    const remove=document.createElement('button');remove.className='extension-action';remove.textContent='remove';remove.onclick=()=>uninstallExtension(ext.id);actions.appendChild(remove);
    installed.appendChild(card);
  }
  if(!installed.children.length)installed.innerHTML='<div class="extension-empty">no custom extensions installed</div>';
}

</script>
  <script>/* p/js/app/tabs.js */
// tab state, kept internal pages and the tab strip

let tabs = [];
let activeTabId = null;
let nextTabId = 1;
let _dragSrcTabId = null;

const getActiveTab = () => tabs.find(t => t.id === activeTabId);
function reloadTab(tab) {
  if (!tab) return;
  clearTimeout(tab.skipTimeout);
  clearTimeout(tab.loadFallbackTimeout);
  // only real urls go through beginLoad. internal pages have no loading state to clear later
  if (tab.page || !tab.url) cancelLoad(tab);
  if (tab.page && window.__pageURLs?.[tab.page]) {
    if (tab.keptShown && tab.kept?.[tab.keptShown]) tab.kept[tab.keptShown].src = window.__pageURLs[tab.page];
    else tab.frame.frame.src = window.__pageURLs[tab.page];
  } else if (tab.url) {
    beginLoad(tab, true);
    tab.frame.go(tab.url);
  } else {
    tab.frame.frame.src = 'about:blank';
  }
  if (tab.id === activeTabId) {
    setBrowserMode(tab.forceChrome || (!tab.page && Boolean(tab.url)));
    if (tab.page) showIframeLoading(false);
  }
  updateTabsUI();
  updateAddressBar();
}

function ensureKept(tab, name) {
  tab.kept = tab.kept || {};
  if (!tab.kept[name]) {
    const el = document.createElement('iframe');
    el.className = 'hidden';
    el.setAttribute('referrerpolicy', 'no-referrer');
    el.setAttribute('allow', 'autoplay; fullscreen; clipboard-write; microphone; camera; display-capture');
    el.src = window.__pageURLs[name];
