// page load detection and the loading bar

function showIframeLoading(show) {
  const tab=getActiveTab(); if(!tab) return;
  const on=!!show && !!tab._cover;
  tab.frame.frame.classList.toggle('loading', on);
  const el=document.getElementById('page-loading'); if(el) el.style.display=on?'flex':'none';
}

const SEARCH_RESULT_SEL = '#links,[data-testid="mainline"],[data-testid="result"],#search,#rso,#b_results,#results';
const SEARCH_HOST = /(^|\.)(duckduckgo\.com|google\.[a-z.]+|bing\.com|brave\.com)$/i;
function hasVisibleContent(d) {
  const skip = /^(SCRIPT|STYLE|LINK|META|NOSCRIPT|TEMPLATE|HEAD|TITLE)$/;
  for (const el of d.body.querySelectorAll('*')) {
    if (skip.test(el.tagName) || !el.offsetWidth || !el.offsetHeight) continue;
    if (/^(IMG|CANVAS|VIDEO|IFRAME|INPUT|SVG)$/i.test(el.tagName)) return true;
    if (!el.children.length && el.textContent.trim()) return true;
  }
  return false;
}
function isSearchPage(url) {
  try { const u = new URL(url); return SEARCH_HOST.test(u.hostname) && u.searchParams.has('q'); } catch { return false; }
}
function pageReady(tab, elapsed) {
  let d; try { d = tab.frame.frame.contentDocument; } catch { return elapsed > 1500; }
  if (!d || !d.body) return false;
  if (d.body.dataset && d.body.dataset.view) return false;
  if (d === tab._baseDoc && (tab._cover || elapsed < 1500)) return false;
  if (isSearchPage(tab._pendingUrl) || isSearchPage(tab.url)) {
    if (d.querySelector(SEARCH_RESULT_SEL)) return true;
    return elapsed > 8000 && hasVisibleContent(d);
  }
  return hasVisibleContent(d);
}
function beginLoad(tab, cover) {
  clearInterval(tab._poll); clearTimeout(tab.skipTimeout); clearTimeout(tab.loadFallbackTimeout);
  tab.loading = true; tab._cover = !!cover; tab._t0 = Date.now();
  try { tab._baseDoc = tab.frame.frame.contentDocument; } catch { tab._baseDoc = null; }
  if (tab.id === activeTabId) showIframeLoading(true);
  updateLoadingBar(tab, 10); updateTabsUI();
  tab._poll = setInterval(() => {
    const el = Date.now() - tab._t0;
    if (pageReady(tab, el) || el > 15000) endLoad(tab);
    else updateLoadingBar(tab, Math.min(90, 10 + el / 120));
  }, 150);
}
function cancelLoad(tab) {
  clearInterval(tab._poll);
  tab.loading = false; tab._cover = false; tab._baseDoc = null; tab._pendingUrl = '';
  tab.frame.frame.classList.remove('loading');
  if (tab.id === activeTabId) showIframeLoading(false);
}
function endLoad(tab) {
  cancelLoad(tab);
  if (tab.id === activeTabId) setBrowserMode(tab.forceChrome || (!tab.page && Boolean(tab.url)));
  try { const title = tab.frame.frame.contentWindow.document.title; if (title && !tab.page) tab.title = title; } catch {}
  updateTabsUI(); updateAddressBar(); updateLoadingBar(tab, 100);
}

function updateLoadingBar(tab, percent) {
  if (tab.id !== activeTabId) return;
  const bar=document.getElementById('loading-bar'); if (!bar) return;
  bar.style.width=percent+'%'; bar.style.opacity=percent===100?'0':'1';
  if (percent===100) setTimeout(()=>{bar.style.width='0%';},200);
}

