function closeWizard() {
  const el = document.getElementById('setup-wizard');
  if (el) el.classList.add('hidden');
}
async function finishWizard() {
  markSetupDone();
  closeWizard();
  queueSettingsSync();
  if (getSetting('proxy') !== bootProxy) {
    if (sb && sbUser) await pushSettings();
    __loc.reload();
    return;
  }
  maybeStartTour();
}

function renderWizard() {
  const step = WIZARD_STEPS[wizardIndex];
  const last = wizardIndex === WIZARD_STEPS.length - 1;
  const $ = id => document.getElementById(id);
  $('wizard-title').textContent = step.title;
  $('wizard-sub').textContent = step.sub;
  $('wizard-dots').innerHTML = WIZARD_STEPS.map((_, i) => `<span class="wizard-dot${i === wizardIndex ? ' on' : ''}"></span>`).join('');
  $('wizard-back').style.visibility = wizardIndex ? 'visible' : 'hidden';
  $('wizard-next').style.display = last ? 'none' : '';
  $('wizard-skip').style.display = last ? '' : 'none';
  $('wizard-signin').style.display = last ? 'none' : '';
  const body = $('wizard-body');
  body.innerHTML = '';

  if (step.id === 'theme') {
    const list = document.createElement('div');
    list.className = 'theme-list';
    THEMES.forEach(theme => {
      const el = document.createElement('button');
      el.type = 'button';
      el.className = 'theme-swatch' + (theme.key === getTheme() ? ' active' : '');
      el.innerHTML = `<span class="theme-dot" style="background:${theme.dot}"></span>${escapeHtml(theme.label)}`;
      el.onclick = () => { applyTheme(theme.key); renderWizard(); };
      list.appendChild(el);
    });
    body.appendChild(list);
  }

  if (step.id === 'background') {
    const grid = document.createElement('div');
    grid.className = 'wizard-bgs';
    const current = getCustomBackground();
    const sphere = '<svg viewBox="0 0 100 62" fill="none" stroke="currentColor" stroke-width="0.8" opacity="0.6"><circle cx="50" cy="31" r="24"/><ellipse cx="50" cy="31" rx="24" ry="8"/><ellipse cx="50" cy="31" rx="24" ry="16"/><ellipse cx="50" cy="31" rx="8" ry="24"/><ellipse cx="50" cy="31" rx="16" ry="24"/><line x1="26" y1="31" x2="74" y2="31"/></svg>';
    const add = (label, image, active, pick, preview) => {
      const el = document.createElement('button');
      el.type = 'button';
      el.className = 'wizard-bg' + (active ? ' active' : '');
      if (image) el.style.backgroundImage = `url("${image}")`;
      el.innerHTML = (preview || '') + `<span>${escapeHtml(label)}</span>`;
      el.onclick = () => { pick(); renderWizard(); };
      grid.appendChild(el);
    };
    add('3d', '', !current, () => setSelectedWallpaper(''), sphere);
    wallpapers.forEach(w => {
      const url = wallpaperImageUrl(w.url);
      add(w.name, url, current === url, () => setSelectedWallpaper(w.url));
    });
    body.appendChild(grid);
  }

  if (step.id === 'font') {
    const list = document.createElement('div');
    list.className = 'theme-list';
    FONTS.forEach(font => {
      const el = document.createElement('button');
      el.type = 'button';
      el.className = 'theme-swatch' + (font.key === getSetting('font') ? ' active' : '');
      el.style.fontFamily = font.css;
      el.textContent = font.label;
      el.onclick = () => { setSetting('font', font.key); applyStoredSettings(); sendThemeToNtTabs(); renderWizard(); };
      list.appendChild(el);
    });
    body.appendChild(list);
  }

  if (step.id === 'proxy') {
    const list = document.createElement('div');
    list.className = 'theme-list';
    PROXIES.forEach(proxy => {
      const el = document.createElement('button');
      el.type = 'button';
      el.className = 'theme-swatch' + (proxy.key === getSetting('proxy') ? ' active' : '');
      el.textContent = proxy.label;
      el.onclick = () => { setSetting('proxy', proxy.key); renderWizard(); };
      list.appendChild(el);
    });
    const note = document.createElement('p');
    note.className = 'wizard-sub';
    note.style.marginTop = '12px';
    note.textContent = (PROXIES.find(x => x.key === getSetting('proxy')) || PROXIES[0]).note;
    body.appendChild(list);
    body.appendChild(note);
  }

  if (step.id === 'account') renderAuthForm(body, wizardMode, finishWizard);
}

function initWizard() {
  const $ = id => document.getElementById(id);
  $('wizard-next').onclick = () => { wizardIndex = Math.min(wizardIndex + 1, WIZARD_STEPS.length - 1); renderWizard(); };
  $('wizard-back').onclick = () => { wizardIndex = Math.max(wizardIndex - 1, 0); renderWizard(); };
  $('wizard-skip').onclick = finishWizard;
  $('wizard-signin').onclick = () => { wizardMode = 'signin'; wizardIndex = WIZARD_STEPS.length - 1; renderWizard(); };
  if (!isSetupDone()) openWizard(0);
}

