  <script>/* p/js/app/tour.js */
// first-run guided tour: dims everything except one part of the ui at a time

// el: a selector inside the home page frame, or { shell: selector } for the browser chrome. no el = centred card
const TOUR_STEPS = [
  { title: 'welcome to mochii', text: 'quick tour of where everything is. takes about 30 seconds.' },
  { el: '.rail-nav', side: 'below', title: 'the topbar', text: 'this is where all your stuff lies. jump between home, games, chat and ai from here.' },
  { el: '.rail-foot', side: 'below', title: 'discord and settings', text: 'join the discord, or open settings to change your theme, wallpaper, font and proxy server.' },
  { el: '.acct-pill:not([hidden])', side: 'below', title: 'your account', text: 'your profile. it keeps your settings and search history synced, and it\'s your chat account too.' },
  { el: '#f', side: 'below', title: 'search', text: 'type anything to search, or paste a url to open it. press / to jump here from anywhere on the home page.' },
  { el: '#bm', side: 'above', title: 'bookmarks', text: 'your favourite sites live here. hit + to add one.' },
  { shell: '.main-nav', chrome: true, side: 'below', title: 'the browser bar', text: 'once you open a site this bar shows up: back, forward, reload, the address bar, home, devtools and settings.' },
  { shell: '#tabbar', chrome: true, side: 'below', title: 'tabs', text: 'open up to 12 tabs. drag to reorder, and press + for a new one.' },
  { title: 'one more thing', text: () => `press ${PALETTE_KEY} anywhere to open the command palette. it finds pages, tabs, bookmarks, themes and actions.` },
  { title: 'you\'re all set', text: 'you can replay this tour any time from settings → about, or from the command palette.' }
];
let tourEl = null, tourIndex = 0, tourShown = [], tourRaf = 0, tourChrome = false;

function isTourDone() { try { return localStorage.getItem('mochiiTourDone') === '1'; } catch { return true; } }
function markTourDone() { try { localStorage.setItem('mochiiTourDone', '1'); } catch {} }

function tourHomeDoc() {
  const tab = getActiveTab();
  if (!tab || tab.page !== 'home' || tab.keptShown) return null;
  try { return tab.frame.frame.contentDocument; } catch { return null; }
}
// finds the step's element and its rect in page coordinates (frame rects are offset by the iframe)
function tourTarget(step) {
  if (step.shell) { const el = document.querySelector(step.shell); return el && el.offsetParent !== null ? el.getBoundingClientRect() : null; }
  if (!step.el) return null;
  const doc = tourHomeDoc(), el = doc?.querySelector(step.el);
  if (!el || !el.getClientRects().length) return null;
  const r = el.getBoundingClientRect(), f = getActiveTab().frame.frame.getBoundingClientRect();
  return { left: r.left + f.left, top: r.top + f.top, width: r.width, height: r.height };
}

function setTourChrome(on) {
  if (tourChrome === on) return;
  tourChrome = on;
  const tab = getActiveTab();
  setBrowserMode(on || !!(tab && (tab.forceChrome || (!tab.page && tab.url))));
}

async function startTour() {
  if (tourEl || !document.getElementById('browser-container')) return;
  const tab = getActiveTab();
  if (!tab || tab.page !== 'home' || tab.keptShown) goHome();
  // wait for the home page to load so its elements can be found
  for (let i = 0; i < 50 && !tourHomeDoc()?.querySelector('.rail-nav'); i++) await new Promise(r => setTimeout(r, 100));
  const doc = tourHomeDoc();
  // skip steps whose element doesn't exist (e.g. the account pill when signed out)
  tourShown = TOUR_STEPS.filter(s => !s.el || doc?.querySelector(s.el));
  tourIndex = 0;
  tourEl = document.createElement('div');
  tourEl.className = 'tour';
  tourEl.innerHTML = `<div class="tour-hole"></div><div class="tour-card" role="dialog" aria-modal="true" aria-labelledby="tour-title" aria-describedby="tour-text"><div class="tour-count" id="tour-count"></div><h2 id="tour-title"></h2><p id="tour-text"></p><div class="tour-actions"><button class="btn tour-skip" id="tour-skip" type="button">skip tour</button><button class="btn" id="tour-back" type="button">back</button><button class="btn primary" id="tour-next" type="button">next</button></div></div>`;
  document.body.appendChild(tourEl);
  tourEl.querySelector('#tour-skip').onclick = endTour;
  tourEl.querySelector('#tour-back').onclick = () => showTourStep(tourIndex - 1);
  tourEl.querySelector('#tour-next').onclick = () => tourIndex === tourShown.length - 1 ? endTour() : showTourStep(tourIndex + 1);
  window.addEventListener('keydown', tourKeys, true);
  showTourStep(0);
  tourRaf = requestAnimationFrame(placeTour);
}

function endTour() {
  if (!tourEl) return;
  markTourDone();
  cancelAnimationFrame(tourRaf);
  window.removeEventListener('keydown', tourKeys, true);
  setTourChrome(false);
  tourEl.remove(); tourEl = null;
}

function tourKeys(e) {
  if (!tourEl) return;
  if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); endTour(); }
  else if (e.key === 'ArrowRight' || e.key === 'Enter') { e.preventDefault(); e.stopPropagation(); tourEl.querySelector('#tour-next').click(); }
  else if (e.key === 'ArrowLeft' && tourIndex) { e.preventDefault(); e.stopPropagation(); showTourStep(tourIndex - 1); }
}

function showTourStep(i) {
  tourIndex = Math.max(0, Math.min(i, tourShown.length - 1));
  const step = tourShown[tourIndex], last = tourIndex === tourShown.length - 1;
  setTourChrome(!!step.chrome);
  tourEl.querySelector('#tour-count').textContent = `${tourIndex + 1} / ${tourShown.length}`;
  tourEl.querySelector('#tour-title').textContent = step.title;
  tourEl.querySelector('#tour-text').textContent = typeof step.text === 'function' ? step.text() : step.text;
  tourEl.querySelector('#tour-back').style.visibility = tourIndex ? 'visible' : 'hidden';
  tourEl.querySelector('#tour-skip').style.visibility = last ? 'hidden' : 'visible';
  tourEl.querySelector('#tour-next').textContent = last ? 'done' : tourIndex ? 'next' : 'show me around';
  const card = tourEl.querySelector('.tour-card');
  card.classList.remove('in'); void card.offsetWidth; card.classList.add('in');
  tourEl.querySelector('#tour-next').focus();
}

// runs every frame so the spotlight follows layout changes (chrome sliding in, resizes, the frame loading)
function placeTour() {
  if (!tourEl) return;
  tourRaf = requestAnimationFrame(placeTour);
  const hole = tourEl.firstChild, card = tourEl.lastChild, step = tourShown[tourIndex];
  const vw = innerWidth, vh = innerHeight, gap = 14, pad = 8, edge = 16;
  const r = tourTarget(step);
  if (!r) {
    hole.style.cssText = `left:${vw / 2}px;top:${vh / 2}px;width:0;height:0;box-shadow:0 0 0 200vmax rgba(0,0,0,.72)`;
    card.style.left = Math.max(edge, (vw - card.offsetWidth) / 2) + 'px';
    card.style.top = Math.max(edge, (vh - card.offsetHeight) / 2) + 'px';
    return;
  }
  const x = r.left - pad, y = r.top - pad, w = r.width + pad * 2, h = r.height + pad * 2;
  hole.style.cssText = `left:${x}px;top:${y}px;width:${w}px;height:${h}px`;
  const cw = card.offsetWidth, ch = card.offsetHeight;
  const below = y + h + gap, above = y - gap - ch;
  let top = step.side === 'above' ? (above >= edge ? above : below) : (below + ch <= vh - edge ? below : above);
  top = Math.max(edge, Math.min(top, vh - ch - edge));
  const left = Math.max(edge, Math.min(x + w / 2 - cw / 2, vw - cw - edge));
  card.style.left = left + 'px'; card.style.top = top + 'px';
}

// shows the tour once, after the setup wizard is finished and the browser is up
function maybeStartTour() {
  const wizard = document.getElementById('setup-wizard');
  if (isTourDone() || !isSetupDone() || (wizard && !wizard.classList.contains('hidden'))) return;
  startTour();
}

