  <script>/* p/js/app/palette.js */
// command palette (ctrl/cmd+k): jump to pages, tabs, bookmarks, themes, servers and actions

const PALETTE_KEY = /mac|iphone|ipad/i.test(navigator.platform) ? '⌘k' : 'ctrl k';
let paletteEl = null, paletteShown = [], paletteIndex = 0;

function paletteHost(url) { try { return new URL(url).hostname.replace(/^www\./, ''); } catch { return ''; } }
function paletteFavicon(url) { const h = paletteHost(url); return h ? `<img src="https://www.google.com/s2/favicons?domain=${encodeURIComponent(h)}&sz=32" alt="">` : icon('search', 16); }

function paletteCommands() {
  const cmds = [], add = (group, label, run, o = {}) => cmds.push({ group, label, run, ...o });
  const tab = getActiveTab(), browsing = !!(tab && !tab.page && tab.url);
  if (tabs.length > 1) tabs.forEach(t => add('tabs', t.title || 'new tab', () => switchTab(t.id), {
    hint: t.id === activeTabId ? 'current' : t.url ? paletteHost(t.url) : '',
    icon: t.favicon ? `<img src="${escapeHtml(t.favicon)}" alt="">` : t.page ? pgIcon(t.page, 16) : icon('search', 16) }));
  Object.entries(PAGE_TITLES).forEach(([p, t]) => add('pages', t, () => { const a = getActiveTab(); if (a) { a.forceChrome = false; openPage(p, a); } }, { icon: pgIcon(p, 16), hint: tab?.page === p ? 'current' : '' }));
  add('actions', 'new tab', () => createTab(true, 'home', { forceChrome: true }), { icon: icon('plus', 16) });
  add('actions', 'close tab', () => closeTab(activeTabId), { icon: pgIcon('close', 16) });
  add('actions', 'reload', () => reloadTab(getActiveTab()), { icon: icon('reload', 16) });
  if (tab && tab.historyIndex > 0) add('actions', 'go back', () => navigateHistory(-1), { icon: icon('back', 16) });
  if (tab && tab.historyIndex < tab.historyStack.length - 1) add('actions', 'go forward', () => navigateHistory(1), { icon: icon('forward', 16) });
  if (browsing) add('actions', 'devtools', toggleDevTools, { icon: icon('dev', 16) });
  add('actions', 'settings', () => { openSettings(); setSettingsSection('preferences'); }, { icon: icon('settings', 16) });
  add('actions', 'appearance', () => { openSettings(); setSettingsSection('appearance'); }, { icon: icon('settings', 16), keys: 'wallpaper font' });
  add('actions', 'account', () => { openSettings(); setSettingsSection('account'); }, { icon: pgIcon('account', 16) });
  add('actions', 'take the tour', startTour, { icon: icon('home', 16), keys: 'help tutorial guide' });
  add('actions', 'discord', () => handleSubmit(DISCORD_URL), { icon: pgIcon('discord', 16) });
  let marks = DEFAULT_BOOKMARKS;
  try { marks = JSON.parse(localStorage.getItem('gl_shortcuts') || 'null') || DEFAULT_BOOKMARKS; } catch {}
  marks.forEach(b => add('bookmarks', b.label, () => handleSubmit(b.url), { hint: paletteHost(b.url), icon: paletteFavicon(b.url) }));
  const theme = getTheme();
  THEMES.forEach(t => add('themes', 'theme: ' + t.label, () => applyTheme(t.key), { hint: t.key === theme ? 'current' : '', icon: `<span class="palette-dot" style="background:${t.dot}"></span>` }));
  const server = localStorage.getItem('proxServer') || DEFAULT_WISP;
  getAllWispServers().forEach(s => add('servers', 'server: ' + s.name, () => setWisp(s.url), { hint: s.url === server ? 'current' : 'reloads', keys: s.url, icon: icon('reload', 16) }));
  return cmds;
}

function paletteScore(q, text) {
  const s = text.toLowerCase(), i = s.indexOf(q);
  if (i === 0) return 4;
  if (i > 0) return /[\s:.\-]/.test(s[i - 1]) ? 3 : 2;
  let j = 0;
  for (const c of s) if (c === q[j]) j++;
  return j === q.length ? 1 : 0;
}

function renderPalette() {
  const input = document.getElementById('palette-input'), list = document.getElementById('palette-list');
  const raw = input.value.trim(), q = raw.toLowerCase();
  let shown = paletteCommands();
  if (q) {
    shown = shown.map((c, n) => ({ c, n, s: Math.max(paletteScore(q, c.label), paletteScore(q, c.keys || '') > 1 ? 1 : 0, paletteScore(q, c.group) > 1 ? 1 : 0) }))
      .filter(x => x.s).sort((a, b) => b.s - a.s || a.n - b.n).map(x => x.c);
    const isSearch = resolveInput(raw) === getSearchUrl(raw);
    shown.unshift({ group: 'go', label: isSearch ? `search "${raw}"` : `go to ${raw}`, run: () => handleSubmit(raw), icon: isSearch ? icon('search', 16) : paletteFavicon(resolveInput(raw)), hint: 'enter' },
      { group: 'go', label: `${isSearch ? 'search' : 'open'} in new tab`, run: () => openUrlInNewTab(raw), icon: icon('plus', 16) });
  }
  paletteShown = shown;
  paletteIndex = Math.min(paletteIndex, Math.max(0, shown.length - 1));
  let html = '', last = '';
  shown.forEach((c, i) => {
    if (!q && c.group !== last) html += `<div class="palette-group">${c.group}</div>`;
    last = c.group;
    const hint = q && c.group !== 'go' ? (c.hint && c.hint !== 'reloads' ? c.hint : c.group) : (c.hint || '');
    html += `<div class="palette-item${i === paletteIndex ? ' active' : ''}" role="option" id="palette-opt-${i}" data-i="${i}" aria-selected="${i === paletteIndex}"><span class="palette-icon">${c.icon || ''}</span><span class="palette-label">${escapeHtml(c.label)}</span>${hint ? `<span class="palette-hint${hint === 'current' ? ' current' : ''}">${escapeHtml(hint)}</span>` : ''}</div>`;
  });
  list.innerHTML = html || '<div class="palette-empty">nothing found</div>';
  input.setAttribute('aria-activedescendant', shown.length ? 'palette-opt-' + paletteIndex : '');
}

function movePalette(i) {
  const list = document.getElementById('palette-list');
  list.querySelector('.palette-item.active')?.classList.remove('active');
  paletteIndex = (i + paletteShown.length) % paletteShown.length;
  const el = list.querySelector(`[data-i="${paletteIndex}"]`);
  if (!el) return;
  el.classList.add('active'); el.scrollIntoView({ block: 'nearest' });
  document.getElementById('palette-input').setAttribute('aria-activedescendant', el.id);
}

function runPalette(i) {
  const cmd = paletteShown[i];
  if (!cmd) return;
  closePalette();
  try { cmd.run(); } catch (e) { console.warn('palette command failed', e); }
}

function buildPalette() {
  paletteEl = document.createElement('div');
  paletteEl.className = 'palette hidden';
  paletteEl.innerHTML = `<div class="palette-card" role="dialog" aria-modal="true" aria-label="command palette">
    <div class="palette-search">${icon('search', 18)}<input id="palette-input" type="text" autocomplete="off" spellcheck="false" placeholder="search, jump to a page or run a command" role="combobox" aria-expanded="true" aria-controls="palette-list"><kbd>esc</kbd></div>
    <div class="palette-list" id="palette-list" role="listbox"></div>
    <div class="palette-foot"><span><kbd>↑</kbd><kbd>↓</kbd> move</span><span><kbd>enter</kbd> open</span><span class="grow"></span><span><kbd>${PALETTE_KEY}</kbd> toggle</span></div></div>`;
  document.body.appendChild(paletteEl);
  const input = paletteEl.querySelector('input'), list = paletteEl.querySelector('.palette-list');
  input.addEventListener('input', () => { paletteIndex = 0; renderPalette(); list.scrollTop = 0; });
  input.addEventListener('keydown', e => {
    if (e.key === 'ArrowDown' || (e.key === 'Tab' && !e.shiftKey)) { e.preventDefault(); movePalette(paletteIndex + 1); }
    else if (e.key === 'ArrowUp' || (e.key === 'Tab' && e.shiftKey)) { e.preventDefault(); movePalette(paletteIndex - 1); }
    else if (e.key === 'Enter') { e.preventDefault(); runPalette(paletteIndex); }
    else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); closePalette(); }
  });
  list.addEventListener('mousemove', e => { const it = e.target.closest('.palette-item'); if (it && +it.dataset.i !== paletteIndex) movePalette(+it.dataset.i); });
  list.addEventListener('click', e => { const it = e.target.closest('.palette-item'); if (it) runPalette(+it.dataset.i); });
  paletteEl.addEventListener('mousedown', e => { if (e.target === paletteEl) closePalette(); });
}

function openPalette() {
  if (!tabs.length) return;
  if (!paletteEl) buildPalette();
  const input = document.getElementById('palette-input');
  input.value = ''; paletteIndex = 0;
  renderPalette();
  paletteEl.classList.remove('hidden');
  input.focus();
}
function closePalette() { paletteEl?.classList.add('hidden'); }
function togglePalette() { if (paletteEl && !paletteEl.classList.contains('hidden')) closePalette(); else openPalette(); }

window.addEventListener('keydown', e => {
  if ((e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey && e.key.toLowerCase() === 'k') { e.preventDefault(); togglePalette(); }
});

