  <script>/* p/js/app/main.js */
// startup. loaded last, after every other file has defined its functions

async function proxyInit() {
  const root=document.getElementById('proxy-app');
  root.innerHTML=`<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:var(--bg-body)"><div style="display:flex;flex-direction:column;align-items:center;gap:12px;color:var(--text-muted);font-size:12px"><div class="spinner" style="margin:0"></div><div>starting mochii...</div></div></div>`;

  await initializeExtensions();
  await buildInternalPages();

  try {
    await fetchWispServers();
    await initializeWithBestServer();
    await initProxyEngine();
    try { await getSharedConnection(); } catch (e) { const alt = getAllWispServers().find(s => s.url !== localStorage.getItem('proxServer')); if (!alt) throw e; localStorage.setItem('proxServer', alt.url); sharedConnectionReady = false; await getSharedConnection(); }

    if ('serviceWorker' in navigator) {
      const reg=await navigator.serviceWorker.register(getBasePath()+'sw.js',{scope:getBasePath()});
      await navigator.serviceWorker.ready;
      const wispUrl=localStorage.getItem('proxServer') || DEFAULT_WISP;
      const config={type:'config',wispurl:wispUrl,servers:getAllWispServers(),autoswitch:localStorage.getItem('wispAutoswitch')!=='false'};
      navigator.serviceWorker.addEventListener('message', async ({ data }) => { if (data?.type === 'blocked') return recordBlocked(data); if (data?.type !== 'wispChanged' || !data.url) return; localStorage.setItem('proxServer', data.url); try { await sharedConnection.setTransport(TRANSPORT_URL, [{ wisp: data.url }]); } catch {} });
      const send=()=>{const sw=reg.active||navigator.serviceWorker.controller;if(sw)sw.postMessage(config);};
      send(); setTimeout(send,500); setTimeout(send,1500); reg.update();
    }

    await initializeBrowser();
    maybeStartTour();
  } catch(err) {
    console.error('proxy initialization error:',err);
    root.innerHTML=`<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:var(--bg-body)"><div class="message-content"><h1>init error</h1><p>${escapeHtml(err?.message || 'unknown error')}</p><button class="message-button" onclick="__loc.reload()">retry</button></div></div>`;
  }
}

window.addEventListener('message', event => {
  if(event.data?.type==='GHOSTLINK_NT_READY') { sendThemeToNtTabs(); sendAccountToNtTabs(); sendMusicToNtTabs(true); }
});

try {
  const savedTheme = getTheme();
  if (savedTheme !== 'default') document.documentElement.setAttribute('data-theme', savedTheme);
  if (savedTheme === 'auto') applyAutoTheme();
} catch {}
applyStoredSettings();
